def gen(draw):
    n = draw(st.integers(1, 5)) * 2
    half = n // 2
    alphabet = draw(st.sampled_from(["ab", "abc", "a", "xyz"]))
    s = draw(st.text(alphabet=alphabet, min_size=n, max_size=n))
    q_count = draw(st.integers(1, 4))
    queries = []
    for _ in range(q_count):
        a = draw(st.integers(0, half - 1))
        b = draw(st.integers(a, half - 1))
        c = draw(st.integers(half, n - 1))
        d = draw(st.integers(c, n - 1))
        queries.append([a, b, c, d])
    return json.dumps(s) + "\n" + json.dumps(queries) + "\n"


