    s = json.loads(lines[0])
    queries = json.loads(lines[1])
    n = len(s)
    half = n // 2
    result = []
    for a, b, c, d in queries:
        # Left segment s[a:b+1] can be permuted in place; right segment s[c:d+1] too.
        left_mid = s[a:b + 1]
        right_mid = s[c:d + 1]
        left_perms = set("".join(p) for p in itertools.permutations(left_mid))
        right_perms = set("".join(p) for p in itertools.permutations(right_mid))
        ok = False
        for lp in left_perms:
